mkitem!{mkstruct!{# [doc = " `BlockTailInfo` is attached to the `LocalDecl` for temporaries"] # [doc = " created during evaluation of expressions in a block tail"] # [doc = " expression; that is, a block like `{ STMT_1; STMT_2; EXPR }`."] # [doc = ""] # [doc = " It is used to improve diagnostics when such temporaries are"] # [doc = " involved in borrow_check errors, e.g., explanations of where the"] # [doc = " temporaries come from, when their destructors are run, and/or how"] # [doc = " one might revise the code to satisfy the borrow checker's rules."] # [derive (Clone , Copy , Debug , PartialEq , Eq , TyEncodable , TyDecodable , HashStable)] pub struct BlockTailInfo { # [doc = " If `true`, then the value resulting from evaluating this tail"] # [doc = " expression is ignored by the block's expression context."] # [doc = ""] # [doc = " Examples include `{ ...; tail };` and `let _ = { ...; tail };`"] # [doc = " but not e.g., `let _x = { ...; tail };`"] pub tail_result_is_ignored : bool , # [doc = " `Span` of the tail expression."] pub span : Span , }}}
mkitem!{mkstruct!{# [doc = " A MIR local."] # [doc = ""] # [doc = " This can be a binding declared by the user, a temporary inserted by the compiler, a function"] # [doc = " argument, or the return place."] # [derive (Clone , Debug , TyEncodable , TyDecodable , HashStable , TypeFoldable , TypeVisitable)] pub struct LocalDecl < 'tcx > { # [doc = " Whether this is a mutable binding (i.e., `let x` or `let mut x`)."] # [doc = ""] # [doc = " Temporaries and the return place are always mutable."] pub mutability : Mutability , pub local_info : ClearCrossCrate < Box < LocalInfo < 'tcx > > > , # [doc = " The type of this local."] pub ty : Ty < 'tcx > , # [doc = " If the user manually ascribed a type to this variable,"] # [doc = " e.g., via `let x: T`, then we carry that type here. The MIR"] # [doc = " borrow checker needs this information since it can affect"] # [doc = " region inference."] pub user_ty : Option < Box < UserTypeProjections > > , # [doc = " The *syntactic* (i.e., not visibility) source scope the local is defined"] # [doc = " in. If the local was defined in a let-statement, this"] # [doc = " is *within* the let-statement, rather than outside"] # [doc = " of it."] # [doc = ""] # [doc = " This is needed because the visibility source scope of locals within"] # [doc = " a let-statement is weird."] # [doc = ""] # [doc = " The reason is that we want the local to be *within* the let-statement"] # [doc = " for lint purposes, but we want the local to be *after* the let-statement"] # [doc = " for names-in-scope purposes."] # [doc = ""] # [doc = " That's it, if we have a let-statement like the one in this"] # [doc = " function:"] # [doc = ""] # [doc = " ```"] # [doc = " fn foo(x: &str) {"] # [doc = "     #[allow(unused_mut)]"] # [doc = "     let mut x: u32 = {"] # [doc = "         //^ one unused mut"] # [doc = "         let mut y: u32 = x.parse().unwrap();"] # [doc = "         y + 2"] # [doc = "     };"] # [doc = "     drop(x);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Then, from a lint point of view, the declaration of `x: u32`"] # [doc = " (and `y: u32`) are within the `#[allow(unused_mut)]` scope - the"] # [doc = " lint scopes are the same as the AST/HIR nesting."] # [doc = ""] # [doc = " However, from a name lookup point of view, the scopes look more like"] # [doc = " as if the let-statements were `match` expressions:"] # [doc = ""] # [doc = " ```"] # [doc = " fn foo(x: &str) {"] # [doc = "     match {"] # [doc = "         match x.parse::<u32>().unwrap() {"] # [doc = "             y => y + 2"] # [doc = "         }"] # [doc = "     } {"] # [doc = "         x => drop(x)"] # [doc = "     };"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " We care about the name-lookup scopes for debuginfo - if the"] # [doc = " debuginfo instruction pointer is at the call to `x.parse()`, we"] # [doc = " want `x` to refer to `x: &str`, but if it is at the call to"] # [doc = " `drop(x)`, we want it to refer to `x: u32`."] # [doc = ""] # [doc = " To allow both uses to work, we need to have more than a single scope"] # [doc = " for a local. We have the `source_info.scope` represent the \"syntactic\""] # [doc = " lint scope (with a variable being under its let block) while the"] # [doc = " `var_debug_info.source_info.scope` represents the \"local variable\""] # [doc = " scope (where the \"rest\" of a block is under all prior let-statements)."] # [doc = ""] # [doc = " The end result looks like this:"] # [doc = ""] # [doc = " ```text"] # [doc = " ROOT SCOPE"] # [doc = "  │{ argument x: &str }"] # [doc = "  │"] # [doc = "  │ │{ #[allow(unused_mut)] } // This is actually split into 2 scopes"] # [doc = "  │ │                         // in practice because I'm lazy."] # [doc = "  │ │"] # [doc = "  │ │← x.source_info.scope"] # [doc = "  │ │← `x.parse().unwrap()`"] # [doc = "  │ │"] # [doc = "  │ │ │← y.source_info.scope"] # [doc = "  │ │"] # [doc = "  │ │ │{ let y: u32 }"] # [doc = "  │ │ │"] # [doc = "  │ │ │← y.var_debug_info.source_info.scope"] # [doc = "  │ │ │← `y + 2`"] # [doc = "  │"] # [doc = "  │ │{ let x: u32 }"] # [doc = "  │ │← x.var_debug_info.source_info.scope"] # [doc = "  │ │← `drop(x)` // This accesses `x: u32`."] # [doc = " ```"] pub source_info : SourceInfo , }}}
mkitem!{mkenum!{# [doc = " Extra information about a some locals that's used for diagnostics and for"] # [doc = " classifying variables into local variables, statics, etc, which is needed e.g."] # [doc = " for borrow checking."] # [doc = ""] # [doc = " Not used for non-StaticRef temporaries, the return place, or anonymous"] # [doc = " function parameters."] # [derive (Clone , Debug , TyEncodable , TyDecodable , HashStable , TypeFoldable , TypeVisitable)] pub enum LocalInfo < 'tcx > { # [doc = " A user-defined local variable or function parameter"] # [doc = ""] # [doc = " The `BindingForm` is solely used for local diagnostics when generating"] # [doc = " warnings/errors when compiling the current crate, and therefore it need"] # [doc = " not be visible across crates."] User (BindingForm < 'tcx >) , # [doc = " A temporary created that references the static with the given `DefId`."] StaticRef { def_id : DefId , is_thread_local : bool } , # [doc = " A temporary created that references the const with the given `DefId`"] ConstRef { def_id : DefId } , # [doc = " A temporary created during the creation of an aggregate"] # [doc = " (e.g. a temporary for `foo` in `MyStruct { my_field: foo }`)"] AggregateTemp , # [doc = " A temporary created for evaluation of some subexpression of some block's tail expression"] # [doc = " (with no intervening statement context)."] BlockTailTemp (BlockTailInfo) , # [doc = " A temporary created during evaluating `if` predicate, possibly for pattern matching for `let`s,"] # [doc = " and subject to Edition 2024 temporary lifetime rules"] IfThenRescopeTemp { if_then : HirId } , # [doc = " A temporary created during the pass `Derefer` to avoid it's retagging"] DerefTemp , # [doc = " A temporary created for borrow checking."] FakeBorrow , # [doc = " A local without anything interesting about it."] Boring , }}}
mkitem!{mkimpl!{impl < 'tcx > LocalDecl < 'tcx > { pub fn local_info (& self) -> & LocalInfo < 'tcx > { self . local_info . as_ref () . unwrap_crate_local () } # [doc = " Returns `true` only if local is a binding that can itself be"] # [doc = " made mutable via the addition of the `mut` keyword, namely"] # [doc = " something like the occurrences of `x` in:"] # [doc = " - `fn foo(x: Type) { ... }`,"] # [doc = " - `let x = ...`,"] # [doc = " - or `match ... { C(x) => ... }`"] pub fn can_be_made_mutable (& self) -> bool { matches ! (self . local_info () , LocalInfo :: User (BindingForm :: Var (VarBindingForm { binding_mode : BindingMode (ByRef :: No , _) , opt_ty_info : _ , opt_match_place : _ , pat_span : _ , }) | BindingForm :: ImplicitSelf (ImplicitSelfKind :: Imm) ,)) } # [doc = " Returns `true` if local is definitely not a `ref ident` or"] # [doc = " `ref mut ident` binding. (Such bindings cannot be made into"] # [doc = " mutable bindings, but the inverse does not necessarily hold)."] pub fn is_nonref_binding (& self) -> bool { matches ! (self . local_info () , LocalInfo :: User (BindingForm :: Var (VarBindingForm { binding_mode : BindingMode (ByRef :: No , _) , opt_ty_info : _ , opt_match_place : _ , pat_span : _ , }) | BindingForm :: ImplicitSelf (_) ,)) } # [doc = " Returns `true` if this variable is a named variable or function"] # [doc = " parameter declared by the user."] # [inline] pub fn is_user_variable (& self) -> bool { matches ! (self . local_info () , LocalInfo :: User (_)) } # [doc = " Returns `true` if this is a reference to a variable bound in a `match`"] # [doc = " expression that is used to access said variable for the guard of the"] # [doc = " match arm."] pub fn is_ref_for_guard (& self) -> bool { matches ! (self . local_info () , LocalInfo :: User (BindingForm :: RefForGuard)) } # [doc = " Returns `Some` if this is a reference to a static item that is used to"] # [doc = " access that static."] pub fn is_ref_to_static (& self) -> bool { matches ! (self . local_info () , LocalInfo :: StaticRef { .. }) } # [doc = " Returns `Some` if this is a reference to a thread-local static item that is used to"] # [doc = " access that static."] pub fn is_ref_to_thread_local (& self) -> bool { match self . local_info () { LocalInfo :: StaticRef { is_thread_local , .. } => * is_thread_local , _ => false , } } # [doc = " Returns `true` if this is a DerefTemp"] pub fn is_deref_temp (& self) -> bool { match self . local_info () { LocalInfo :: DerefTemp => true , _ => false , } } # [doc = " Returns `true` is the local is from a compiler desugaring, e.g.,"] # [doc = " `__next` from a `for` loop."] # [inline] pub fn from_compiler_desugaring (& self) -> bool { self . source_info . span . desugaring_kind () . is_some () } # [doc = " Creates a new `LocalDecl` for a temporary, mutable."] # [inline] pub fn new (ty : Ty < 'tcx > , span : Span) -> Self { Self :: with_source_info (ty , SourceInfo :: outermost (span)) } # [doc = " Like `LocalDecl::new`, but takes a `SourceInfo` instead of a `Span`."] # [inline] pub fn with_source_info (ty : Ty < 'tcx > , source_info : SourceInfo) -> Self { LocalDecl { mutability : Mutability :: Mut , local_info : ClearCrossCrate :: Set (Box :: new (LocalInfo :: Boring)) , ty , user_ty : None , source_info , } } # [doc = " Converts `self` into same `LocalDecl` except tagged as immutable."] # [inline] pub fn immutable (mut self) -> Self { self . mutability = Mutability :: Not ; self } }}}
